<script setup>
import { computed, ref } from 'vue';
import { ChevronRight, Folder, FolderSearch } from 'lucide-vue-next';

const props = defineProps({ folders: { type: Array, default: () => [] }, currentYear: Number, busy: Boolean });
const emit = defineEmits(['open']);
const selectedYear = ref(''), order = ref('recent');
const format = value => new Intl.NumberFormat('es-PE').format(Number(value) || 0);
function folderYear(path) {
    for (const part of (path || '').split('/').reverse()) {
        const matches = [...part.matchAll(/(?<!\d)((?:19|20)\d{2})(?!\d)/g)].map(match => Number(match[1])).filter(year => year <= props.currentYear);
        if (new Set(matches).size === 1) return matches[0];
    }
    return null;
}
const catalog = computed(() => props.folders.map(folder => ({ ...folder, parent: (folder.path || '').split('/').slice(0,-1).join('/'), label: folder.path?.split('/').filter(Boolean).pop() || folder.repository || 'Carpeta raíz', period: folderYear(folder.path) })));
const years = computed(() => [...new Set(catalog.value.map(folder => folder.period).filter(Boolean))].sort((a,b) => b-a));
const visible = computed(() => catalog.value.filter(folder => !selectedYear.value || (selectedYear.value === 'unknown' ? !folder.period : folder.period === Number(selectedYear.value))).sort((a,b) => (order.value === 'recent' ? (b.period || 0) - (a.period || 0) : 0) || a.label.localeCompare(b.label,'es',{numeric:true,sensitivity:'base'})));
const total = computed(() => catalog.value.reduce((sum,folder) => sum+Number(folder.total),0));
</script>

<template>
    <section class="folder-browser" aria-label="Explorador de carpetas">
        <header class="folder-browser-heading"><div><h2>Carpetas del archivo</h2><p>{{ format(folders.length) }} carpetas con {{ format(total) }} PDF registrados</p></div><div class="folder-browser-filters"><label><span>Año de la carpeta</span><select v-model="selectedYear" aria-label="Año de la carpeta"><option value="">Todos los años</option><option v-for="year in years" :key="year" :value="String(year)">{{ year }}</option><option v-if="catalog.some(folder => !folder.period)" value="unknown">Sin año en el nombre</option></select></label><label><span>Ordenar</span><select v-model="order" aria-label="Ordenar carpetas"><option value="recent">Más recientes</option><option value="name">Por nombre</option></select></label></div></header>
        <div v-if="visible.length" class="folder-directory"><div class="folder-directory-columns" aria-hidden="true"><span>Carpeta</span><span>Año</span><span>Documentos</span><span></span></div><button v-for="folder in visible" :key="folder.id" class="folder-entry" :disabled="busy" :title="`${folder.repository} / ${folder.path || 'Raíz'}`" :aria-label="`Abrir carpeta ${folder.label}, ${format(folder.total)} PDF`" @click="emit('open',folder)"><span class="folder-symbol"><Folder :size="25" :stroke-width="1.4" fill="currentColor" /></span><span class="folder-copy"><strong>{{ folder.label }}</strong><small>{{ folder.repository }}<template v-if="folder.parent"> / {{ folder.parent }}</template></small></span><span class="folder-period" :class="{ 'current-period': folder.period === currentYear }">{{ folder.period || '—' }}<small v-if="folder.period === currentYear">Actual</small></span><span class="folder-total">{{ format(folder.total) }}<small> PDF</small></span><ChevronRight :size="17" /></button></div>
        <div v-else class="folder-browser-empty"><FolderSearch :size="35" /><h3>No hay carpetas para este año</h3><p>Seleccione otro año para continuar.</p><button v-if="selectedYear" @click="selectedYear = ''">Ver todas las carpetas</button></div>
        <footer class="folder-browser-footer">{{ format(visible.length) }} {{ visible.length === 1 ? 'carpeta' : 'carpetas' }}<span>Seleccione una carpeta para ver sus documentos.</span></footer>
    </section>
</template>

