ng:20px 0 10px;font-size:11px;color:#788a9f;line-height:1.7}.folder-browser-empty{padding:65px 20px;text-align:center;color:#70849e}.folder-browser-empty>svg{margin:0 auto 17px}.folder-browser-empty h3{font-size:16px;color:#344f6e;font-weight:550}.folder-browser-empty p{font-size:13px;margin-top:8px}.folder-browser-empty button{margin-top:18px;font-size:12px;color:#185abc;text-decoration:underline;text-underline-offset:4px}.folder-entry:focus-visible,.folder-browser select:focus-visible,.folder-browser-empty button:focus-visible{outline:2px solid #3b71bf;outline-offset:3px}.folder-entry:disabled{opacity:.5;cursor:not-allowed}
